CREATE TEMPORARY VIEW nmv_add_all_tags_${grass_region_without_quote} AS
SELECT
    *
    ,get_all_tag('click',split(feature_detail_omni, '-')[0],if(split(feature_detail_omni,'-')[2] IS NOT NULL, split(feature_detail_omni,'-')[1], NULL),if(split(feature_detail_omni,'-')[2] IS NOT NULL, 
        split(feature_detail_omni,'-')[2], split(feature_detail_omni,'-')[1]),get_feature_prefix(split(feature_detail_omni, '-')[0],click_search_property.search_mid,click_search_property.search_entrance),'null',atc_event_id) as all_tags
    ,get_all_tag('click',source1_mapped_page_type,source1_page_section,source1_target_type,get_feature_prefix(source1_mapped_page_type,source1_search_property.search_mid,source1_search_property.search_entrance),'null',atc_event_id) as source1_all_tags
    ,get_all_tag('click',source2_mapped_page_type,source2_page_section,source2_target_type,get_feature_prefix(source2_mapped_page_type,source2_search_property.search_mid,source2_search_property.search_entrance),'null',atc_event_id) as source2_all_tags
FROM traffic_omni_oa.dwd_order_item_atc_journey_ext_di__reg
WHERE grass_region IN (${grass_region}) and tz_type='local' and first_touchpoint_item=1
and grass_date BETWEEN date_sub(${local_date}, 30) AND ${local_date}
;
