INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_platform_nmv
PARTITION (
     grass_region=${grass_region}
    ,local_date
    ,local_hour
    ,regional_date
    ,regional_hour
)
SELECT
     shop_id
    ,order_item_id AS item_id
    ,order_model_id AS model_id
    ,user_id
    ,CAST(click_common_property.is_ads AS Boolean) AS is_ads
    ,CAST(source1_common_property.is_ads as Boolean)  as source1_is_ads
    ,CAST(source2_common_property.is_ads as Boolean)  as source2_is_ads
    ,click_search_property.search_entrance
    ,source1_search_property.search_entrance AS source1_search_entrance
    ,source2_search_property.search_entrance AS source2_search_entrance
    ,feature_detail_omni AS feature_detail
    ,source1_feature_detail_omni AS source1_feature_detail
    ,source2_feature_detail_omni AS source2_feature_detail
    ,if(feature_group_omni in ('not found','not found atc','not found valid click'),null,feature_group_omni) as feature_group
    ,if(source1_feature_group_omni in ('not found','not found atc','not found valid click'),null,source1_feature_group_omni) as source1_feature_group
    ,if(source2_feature_group_omni in ('not found','not found atc','not found valid click'),null,source2_feature_group_omni) as source2_feature_group
    ,business_line as reporting_business_line
    ,module as reporting_module
    ,object as reporting_object
    ,source1_business_line as source1_reporting_business_line
    ,source1_module as source1_reporting_module
    ,source1_object as source1_reporting_object
    ,source2_business_line as source2_reporting_business_line
    ,source2_module as source2_reporting_module
    ,source2_object as source2_reporting_object
    ,if(is_net_order = 1,order_fraction * atc_prorate * first_touchpoint_item,0) as net_order_cnt
    ,first_touchpoint_item * nmv_usd * atc_prorate as nmv
    ,first_touchpoint_item * nmv * atc_prorate as nmv_local
    ,platform
    ,if(all_tags[4]='null',null,all_tags[4]) as algo_tag
    ,if(source1_all_tags[4]='null',null,source1_all_tags[4]) as source1_algo_tag
    ,if(source2_all_tags[4]='null',null,source2_all_tags[4]) as source2_algo_tag
    ,click_search_property.sort_by AS sort_type
    ,source1_search_property.sort_by AS source1_sort_type
    ,source2_search_property.sort_by AS source2_sort_type
    ,click_search_property.search_mid AS search_mid
    ,source1_search_property.search_mid AS source1_search_mid
    ,source2_search_property.search_mid AS source2_search_mid
    ,click_search_property.keyword AS keyword
    ,source1_search_property.keyword AS source1_keyword
    ,source2_search_property.keyword AS source2_keyword

    ,Date(timestamp_timezone_convert(order_place_timestamp*1000, grass_region, 'yyyy-MM-dd')) AS local_date
    ,Int(timestamp_timezone_convert(order_place_timestamp*1000, grass_region, 'HH')) AS local_hour
    ,Date(timestamp_timezone_convert(order_place_timestamp*1000, 'SG', 'yyyy-MM-dd')) AS regional_date
    ,Int(timestamp_timezone_convert(order_place_timestamp*1000, 'SG', 'HH')) AS regional_hour
FROM nmv_add_all_tags_${grass_region_without_quote}
;
